using UnityEngine;  public class RoboLift : MonoBehaviour {     public CharacterController controller; // 難魂魏 壯 Character Controller     public float liftSpeed = 2f;           // 亂典前潗 禎掖諺?     public float maxHeight = 10f;          // 璥揄夭贍茴? 述櫛診 禎掖諺?     public float minHeight = 0f;           // 經杖茵蟻壯 述櫛診     private Vector3 moveDirection;         // 昆穽設音杖?壓畏孼?     private float startY;                  // 昆妬蟻壯 禎預打 禎 Y      void Start()     {         // 煖春陝諺 壯妬蟻腸?述櫛膣         startY = transform.position.y;     }      void Update()     {         if (Input.GetKey(KeyCode.R))         {             // 콰嵬齧馹 旬儼? 禎魏 張 哀增嵬腸診 茵揄夭贍茴? 述櫛診             if (transform.position.y < startY + maxHeight)             {                 moveDirection.y = liftSpeed;             }             else             {                 moveDirection.y = 0;             }         }         else if (Input.GetKey(KeyCode.F))         {             // 콰嵬齧馹 純了, 禎魏 張 哀增嵬腸診 麟杖茵蟻壯 述櫛診             if (transform.position.y > startY + minHeight)             {                 moveDirection.y = -liftSpeed;             }             else             {                 moveDirection.y = 0;             }         }         else         {             // 퇸泣 幽設曜?張 壯縯執, 前診壯瞬外齧?壓畏孼猥             moveDirection.y = 0;         }          // 厥夭孼諺 壓畏孼猥 特釣?Character Controller         controller.Move(moveDirection * Time.deltaTime);     } } 